import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.DNL3hc5c.js";const g=JSON.parse('{"title":"Tempo Debugging & Introspection","description":"","frontmatter":{},"headers":[],"relativePath":"doc/4-advanced-reference/tempo.debugging.md","filePath":"doc/4-advanced-reference/tempo.debugging.md"}'),o={name:"doc/4-advanced-reference/tempo.debugging.md"};function n(r,e,c,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="tempo-debugging-introspection" tabindex="-1">Tempo Debugging &amp; Introspection <a class="header-anchor" href="#tempo-debugging-introspection" aria-label="Permalink to &quot;Tempo Debugging &amp; Introspection&quot;">​</a></h1><p>Because Tempo encapsulates complex parsing logic and date-time permutations within an immutable class, understanding <em>why</em> a <code>Tempo</code> instance has arrived at its absolute <code>Temporal.ZonedDateTime</code> value can be critical.</p><p>This document outlines the various debugging and introspection mechanisms available to help trace and understand Tempo&#39;s behavior.</p><br><h2 id="static-introspection" tabindex="-1">Static Introspection <a class="header-anchor" href="#static-introspection" aria-label="Permalink to &quot;Static Introspection&quot;">​</a></h2><p>Before an instance is even created, you can inspect the static state of the <code>Tempo</code> class to understand the global configuration and available plugins.</p><h3 id="tempo-config" tabindex="-1"><code>Tempo.config</code> <a class="header-anchor" href="#tempo-config" aria-label="Permalink to &quot;`Tempo.config`&quot;">​</a></h3><p>Returns the collection of current <em>global</em> configuration settings that act as the default for all new <code>Tempo</code> instances. This includes properties like the default <code>locale</code>, <code>timeZone</code>, and formatting layouts.</p><h3 id="tempo-default" tabindex="-1"><code>Tempo.default</code> <a class="header-anchor" href="#tempo-default" aria-label="Permalink to &quot;`Tempo.default`&quot;">​</a></h3><p>Returns the collection of <em>initial</em>, out-of-the-box defaults that <code>Tempo</code> ships with, unaffected by any modifications made via <a href="./../2-core-concepts/tempo.config.html#_2-global-discovery">Global Discovery</a> or <a href="./../2-core-concepts/tempo.config.html"><code>Tempo.init()</code></a>.</p><h3 id="tempo-terms" tabindex="-1"><code>Tempo.terms</code> <a class="header-anchor" href="#tempo-terms" aria-label="Permalink to &quot;`Tempo.terms`&quot;">​</a></h3><p>Returns an array of all currently registered Term plugins. This is useful to verify which plugins have been loaded via <a href="./../3-extending-tempo/tempo.plugin.html"><code>Tempo.use()</code></a>.</p><h3 id="tempo-properties" tabindex="-1"><code>Tempo.properties</code> <a class="header-anchor" href="#tempo-properties" aria-label="Permalink to &quot;`Tempo.properties`&quot;">​</a></h3><p>Returns an array of the available static getters on the <code>Tempo</code> class.</p><h3 id="tempo-parse" tabindex="-1"><code>Tempo.parse</code> <a class="header-anchor" href="#tempo-parse" aria-label="Permalink to &quot;`Tempo.parse`&quot;">​</a></h3><p>Returns the collection of current <em>global</em> parsing rules. This includes the registries of regex patterns (<code>pattern</code>), snippets, and mapped <code>{event}</code> and <code>{period}</code> definitions.</p><hr><h2 id="instance-introspection" tabindex="-1">Instance Introspection <a class="header-anchor" href="#instance-introspection" aria-label="Permalink to &quot;Instance Introspection&quot;">​</a></h2><p>Once a <code>Tempo</code> instance is instantiated, you can inspect its internal state to understand how it was constructed and what logic was applied.</p><h3 id="this-config" tabindex="-1"><code>this.config</code> <a class="header-anchor" href="#this-config" aria-label="Permalink to &quot;`this.config`&quot;">​</a></h3><p>Returns the collection of configuration settings applied to <em>this instance</em>. This is a composite of the global <code>Tempo.config</code> and any specific <code>Tempo.Options</code> passed during instantiation.</p><h3 id="this-parse-result" tabindex="-1"><code>this.parse.result</code> <a class="header-anchor" href="#this-parse-result" aria-label="Permalink to &quot;`this.parse.result`&quot;">​</a></h3><p>This is arguably the most powerful debugging tool within Tempo. The <code>parse.result</code> property contains an array (a history lineage) of all the rule-matches that occurred to produce the current value.</p><p>Because <code>Tempo</code> is chainable (e.g., <code>new Tempo(&#39;xmas&#39;).set({ period: &#39;afternoon&#39; })</code>), the <code>parse.result</code> array will contain an entry for <em>every</em> step in that chain, detailing:</p><ul><li><code>type</code>: The interpreted type of the input (e.g., <code>String</code>, <code>Temporal.ZonedDateTimeLike</code>).</li><li><code>value</code>: The original argument passed to that step.</li><li><code>match</code>: The specific regex pattern or symbol that successfully matched the input.</li><li><code>groups</code>: The resolved components (<code>yy</code>, <code>mm</code>, <code>dd</code>, <code>hh</code>, etc.) extracted from the match.</li><li><code>anchor</code>: The <strong>active reference point</strong> used for this specific match. This provides a &quot;breadcrumb&quot; trail during complex parses where the anchor might shift as components are resolved.</li></ul><h3 id="this-parse-anchor" tabindex="-1"><code>this.parse.anchor</code> <a class="header-anchor" href="#this-parse-anchor" aria-label="Permalink to &quot;`this.parse.anchor`&quot;">​</a></h3><p>Returns the <strong>initial reference point</strong> used for the current parsing operation. This is the baseline &quot;Now&quot; against which relative Terms (like <code>next Monday</code> or <code>ago</code>) are calculated.</p><h3 id="this-term" tabindex="-1"><code>this.term</code> <a class="header-anchor" href="#this-term" aria-label="Permalink to &quot;`this.term`&quot;">​</a></h3><p>Returns a collection containing the evaluated results of all registered Term plugins for this specific instance.</p><h3 id="this-fmt" tabindex="-1"><code>this.fmt</code> <a class="header-anchor" href="#this-fmt" aria-label="Permalink to &quot;`this.fmt`&quot;">​</a></h3><p>Returns a collection containing the pre-calculated string outputs for all currently registered formatting codes.</p><h3 id="primitive-auditing" tabindex="-1">Primitive Auditing <a class="header-anchor" href="#primitive-auditing" aria-label="Permalink to &quot;Primitive Auditing&quot;">​</a></h3><p>If you simply need to see the value represented in different primitive formats, <code>Tempo</code> implements <code>[Symbol.toPrimitive]</code>:</p><ul><li><code>${tempo}</code> (String coercion) outputs the ISO8601 string via <code>this.toString()</code>.</li><li><code>+tempo</code> (Number coercion) outputs the Unix epoch in milliseconds.</li><li><code>tempo.nano</code> outputs the Unix epoch in nanoseconds formatted as a <code>BigInt</code>.</li></ul><hr><h2 id="debugging-and-console-logging" tabindex="-1">Debugging and Console Logging <a class="header-anchor" href="#debugging-and-console-logging" aria-label="Permalink to &quot;Debugging and Console Logging&quot;">​</a></h2><p>Tempo utilizes a central <strong>Diagnostic Engine</strong> (replacing the legacy Logify strategy) that respects configuration flags to provide structured output without polluting the console.</p><h3 id="the-debug-flag" tabindex="-1">The <code>debug</code> Flag <a class="header-anchor" href="#the-debug-flag" aria-label="Permalink to &quot;The `debug` Flag&quot;">​</a></h3><p>When instantiating a <code>Tempo</code>, or globally via <code>Tempo.init()</code>, you can pass <code>{ debug: &#39;debug&#39; }</code> in the options object.</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tempo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;next Friday&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { debug: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;debug&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>When this flag is enabled, Tempo&#39;s Diagnostic Engine will output detailed <code>console.debug</code> logs during parsing. These logs provide a deep-dive look into the Parse Engine&#39;s resolution logic, including:</p><ul><li>The prioritized layout regex patterns evaluated against the string.</li><li>The raw regex groups extracted (e.g., specific day offsets, localized term mappings).</li><li>The intermediate steps in temporal normalization (e.g., resolving aliases, computing time and date).</li><li>The absolute temporal coordinates composed before final instantiation.</li></ul><p><em>Note: The Diagnostic Engine evaluates the <code>debug</code> setting before serializing any string interpolations, guaranteeing zero-cost execution overhead for standard users who do not request debug-level diagnostics.</em></p><h3 id="the-catch-flag" tabindex="-1">The <code>catch</code> Flag <a class="header-anchor" href="#the-catch-flag" aria-label="Permalink to &quot;The `catch` Flag&quot;">​</a></h3><p>By default, <code>Tempo</code> is designed to be resilient. If it encounters parsing errors or invalid inputs, it will gracefully fallback.</p><p>However, if you want <code>Tempo</code> to <em>throw</em> <code>Error</code> objects instead of swallowing them (useful during development or in strict environments), you can pass <code>{ catch: false }</code> in the options:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Throws an Error instead of returning a fallback date</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tempo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;invalid string&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { catch: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><h3 id="⚡-fast-fail-master-guard-debugging" tabindex="-1">⚡ Fast-Fail (Master Guard) Debugging <a class="header-anchor" href="#⚡-fast-fail-master-guard-debugging" aria-label="Permalink to &quot;⚡ Fast-Fail (Master Guard) Debugging&quot;">​</a></h3><p>Tempo uses a <strong>Master Guard</strong> to avoid the expensive regex parsing phase for strings that are obviously not date-time inputs. If you find that a string is not being parsed as expected, it&#39;s possible that the guard is Rejecting it.</p><ol><li><strong>Check characters</strong>: The guard only allows digits, common symbols (<code>-</code>, <code>:</code>, <code>.</code>, <code>T</code>, <code>Z</code>, <code>/</code>, <code>+</code>, <code>#</code>), space, and standard Latin characters.</li><li><strong>Use <code>debug: 5</code></strong>: If a string passes the guard but fails the parser, you will see &quot;conformed groups&quot; logs. If you see <em>nothing</em> and the input is returned as-is (falling back to a timestamp interpretation), then the guard likely rejected the string.</li><li><strong>Invalid String fallback</strong>: If the guard rejects a string and it cannot be parsed as a numeric timestamp, it will result in an Invalid instance (see below).</li></ol><hr><h3 id="invalid-instances" tabindex="-1">Invalid Instances <a class="header-anchor" href="#invalid-instances" aria-label="Permalink to &quot;Invalid Instances&quot;">​</a></h3><p>If a <code>Tempo</code> instance completely fails to instantiate (and <code>{ catch: false }</code> is not set), it returns an empty object. You can check for this using the <code>isValid</code> property:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tempo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t.isValid) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tempo failed to initialize properly&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div>',54)])])}const u=i(o,[["render",n]]);export{g as __pageData,u as default};
